-- CBIT Annex A1 framework import. No actual progress or financial records.
-- Source SHA256: 0ee2abad7112a9139fc5bdb9684b4356290c54e9f12eaac6fc5f6a2d82658cf6
BEGIN;
DO $import$
DECLARE pid uuid; parent_id uuid; node_id uuid; v_indicator_id uuid; item jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN
   RAISE EXCEPTION 'This import requires an authorized database administrator';
 END IF;
 -- Use the established administrative import path; no user identity is impersonated.
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 IF (SELECT count(*) FROM merl.projects WHERE acronym='CBIT')<>1 THEN
   RAISE EXCEPTION 'Expected exactly one registered CBIT project';
 END IF;
 SELECT id INTO pid FROM merl.projects WHERE acronym='CBIT';
 FOR item IN SELECT value FROM jsonb_array_elements($data$[{"code": "OBJ", "type": "project_objective", "parent": null, "title": "To develop Vanuatu’s institutional and human capacities for complying with Enhanced Transparency Framework (ETF) reporting requirements of the Paris Agreement, and implementation and monitoring of Vanuatu’s Nationally Determined Contribution focusing on Energy, Agriculture, Forestry and other Land-use Sectors.", "order": 0}, {"code": "C1", "type": "component", "parent": "OBJ", "title": "Strengthening Vanuatu’s institutional arrangements for a robust MRV system for NDC climate change mitigation and adaptation actions.", "order": 10}, {"code": "O1.1", "type": "outcome", "parent": "C1", "title": "NDC transparency system in place following the UNFCCC modalities, procedures, and guidelines", "order": 20}, {"code": "OP1.1.1", "type": "output", "parent": "O1.1", "title": "Institutional arrangements strengthened.", "order": 30}, {"code": "OP1.1.2", "type": "output", "parent": "O1.1", "title": "Sectoral transparency guidelines and protocols are established for enhanced NDC climate change mitigation, adaptation, and addressing L&D for observed and potential climate change impacts (e.g. extreme weather events and slow onset events).", "order": 80}, {"code": "OP1.1.3", "type": "output", "parent": "O1.1", "title": "Established operational quality control and assurance mechanism.", "order": 110}, {"code": "O1.2", "type": "outcome", "parent": "C1", "title": "Key Ministries, Agencies, Departments, and other stakeholder’s capacity strengthened to track the NDC actions", "order": 140}, {"code": "OP1.2.1", "type": "output", "parent": "O1.2", "title": "Strengthened guidelines on monitoring and reporting of climate financing focusing on domestic and international sources, and both public and private sector.", "order": 150}, {"code": "OP1.2.2", "type": "output", "parent": "O1.2", "title": "Strengthened capacity of national climate changes stakeholders to track the enhanced NDC adaptation actions.", "order": 180}, {"code": "C2", "type": "component", "parent": "OBJ", "title": "Provision of an online platform, tools, and training for a robust MRV system focusing on Energy, Agriculture, Forestry, and other Land-use Sectors.", "order": 200}, {"code": "O2.1", "type": "outcome", "parent": "C2", "title": "Operational digital data integration and sharing system for a robust MRV system hosted by DEPC.", "order": 210}, {"code": "OP2.1.1", "type": "output", "parent": "O2.1", "title": "Upgraded Information Technology (IT) system for a robust MRV system hosted by MOCC based on the existing system.", "order": 220}, {"code": "OP2.1.2", "type": "output", "parent": "O2.1", "title": "Strengthened human capacity on GHG emissions and removal tools, and climate vulnerability assessment through training and peer to peer learning.", "order": 280}]$data$::jsonb) LOOP
   parent_id := NULL;
   IF item->>'parent' IS NOT NULL THEN
     SELECT id INTO STRICT parent_id FROM merl.framework_nodes WHERE project_id=pid AND node_code=item->>'parent';
   END IF;
   INSERT INTO merl.framework_nodes(project_id,parent_node_id,node_code,node_type,title,description,status,sort_order)
   SELECT pid,parent_id,item->>'code',item->>'type',item->>'title','Source: CBIT Project Result Framework (1).docx, Annex A1. Imported planned result; no achieved status asserted.','draft',(item->>'order')::integer
   WHERE NOT EXISTS(SELECT 1 FROM merl.framework_nodes WHERE project_id=pid AND node_code=item->>'code');
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements($data$[{"code": "1.1.1.I", "node": "OP1.1.1", "name": "Qualitative gaps assessment report focusing on institutional, regulatory, human, technology, finance, and capacity building support needed, and stakeholder to meet the transparency framework of enhanced NDC actions.", "unit": "agencies/ministries assessed", "definition": "Qualitative gaps assessment report focusing on institutional, regulatory, human, technology, finance, and capacity building support needed, and stakeholder to meet the transparency framework of enhanced NDC actions.\nBaseline: --\nMid-term: At least 5 national agency/ministry related to ETF reporting as identified in the stakeholder section should be reviewed, and documented.\nFinal target: At least 10 national agency/ministry related to ETF reporting as identified in the stakeholder section should be reviewed, and documented.\nSource: CBIT Project Result Framework (1).docx, Annex A1. Numeric target measures assessment coverage of agencies/ministries, rather than number of reports.", "mov": "Status of gap assessment report containing summary/result of field visits, interviews and surveys with relevant line ministry/govern ment agency staff.", "assumptions": "Sufficient political and institutional support are received to implement recommendations .", "responsible": "PMU", "qualitative": false, "final": 10, "disaggregation": null}, {"code": "1.1.1.II", "node": "OP1.1.1", "name": "A national term of reference of working groups stating roles and responsibilities of stakeholders with specific guideline for participation of women (32 percent women) for data collection, sharing, and processing focusing on mitigation, adaptation, and addressing loss and damage (L&D) for observed and potential climate change impacts (e.g. extreme weather events and slow onset events).", "unit": "qualitative milestone / requirements", "definition": "A national term of reference of working groups stating roles and responsibilities of stakeholders with specific guideline for participation of women (32 percent women) for data collection, sharing, and processing focusing on mitigation, adaptation, and addressing loss and damage (L&D) for observed and potential climate change impacts (e.g. extreme weather events and slow onset events).\nBaseline: Designated institutional working responsibilities exists for some ministry, but not sufficient for ETF.\nMid-term: Inter-ministerial agencies and other institutions identified for national MRV legal and regulatory framework.\nFinal target: Formalized and published national MRV institutional terms of reference stating roles and responsibilities of stakeholders related to national MRV legal and regulatory framework.\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Evidence of agreements/ procedures/ TORs.", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "MoCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": true, "final": null, "disaggregation": "Women: 32 percent participation requirement."}, {"code": "1.1.1.III", "node": "OP1.1.1", "name": "An operational National ETF body.", "unit": "qualitative milestone / requirements", "definition": "An operational National ETF body.\nBaseline: --\nMid-term: Inter-ministerial agencies and other institutions identified for national MRV legal and regulatory framework.\nFinal target: Formalized and operational national ETF body with terms of reference stating roles and responsibilities of stakeholders related to national ETF.\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Evidence of agreements/ procedures/ TORs.", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "MoCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": true, "final": null, "disaggregation": null}, {"code": "1.1.1.IV", "node": "OP1.1.1", "name": "Qualitative Assessment of Institutional Capacity for Transparency. Scale - 1 No designated transparency institution to support and coordinate the planning and implementation of transparency activities under Article 13 of the Paris Agreement exists.", "unit": "institutional capacity scale", "definition": "Qualitative Assessment of Institutional Capacity for Transparency. Scale - 1 No designated transparency institution to support and coordinate the planning and implementation of transparency activities under Article 13 of the Paris Agreement exists.\nBaseline: --\nMid-term: The National ETF roadmap is prepared and adopted. Scale 2 Designated transparency institution exists, but with limited staff and capacity to support and coordinate implementation of transparency activities under Article 13 of Paris Agreement. Institution lacks authority or mandate to coordinate transparency activities under Article 13.\nFinal target: Established and operational National ETF body under the Climate Change Division of MECDM involving relevant ministries and entities for national ETF reporting. Scale 3. Designated transparency institution has an organizational unit with standing staff with some capacity to coordinate and implement transparency activities under Article 13 of the Paris Agreement. Institution has authority or mandate to coordinate transparency activities under Article 13. Activities are not integrated into national planning or budgeting activities\nSource: CBIT Project Result Framework (1).docx, Annex A1. Source continuation retains its reference to Climate Change Division of MECDM; this agency wording needs verification for Vanuatu. Baseline column is unspecified; Scale 1 is rubric text, not an asserted baseline.", "mov": "National ETF roadmap and Established and operational National ETF body.", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "MoCC PMU", "qualitative": true, "final": null, "disaggregation": null}, {"code": "1.1.2.I", "node": "OP1.1.2", "name": "Number of regulatory frameworks reviewed and formulated guidelines and action plan.", "unit": "qualitative milestone / requirements", "definition": "Number of regulatory frameworks reviewed and formulated guidelines and action plan.\nBaseline: --\nMid-term: Based on the regulatory frameworks reviewed interministerial agencies and other institutions identified for national guideline and action plan.\nFinal target: Published national guideline and action plan.\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Status of national guideline and action plan report containing summary/result of interviews and surveys with relevant line ministry/govern ment agency staff.", "assumptions": "Sufficient political and institutional support are received to implement recommendations .", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": true, "final": null, "disaggregation": null}, {"code": "1.1.2.II", "node": "OP1.1.2", "name": "Number of metrics and indicators for monitoring enhanced NDC actions focusing on climate change mitigation, adaptation, and addressing L&D.", "unit": "qualitative milestone / requirements", "definition": "Number of metrics and indicators for monitoring enhanced NDC actions focusing on climate change mitigation, adaptation, and addressing L&D.\nBaseline: --\nMid-term: Climate change mitigation (at least 4), adaptation (at least 4), and addressing L&D (at least 4).\nFinal target: Climate change mitigation (at least 6), adaptation (at least 6), and addressing L&D (at least 6).\nSource: CBIT Project Result Framework (1).docx, Annex A1. Compound target retained in full; no aggregate count inferred.", "mov": "Evidence of agreed indicators", "assumptions": "Sufficient political and institutional support are received to implement recommendations .", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": true, "final": null, "disaggregation": "Mitigation, adaptation and loss and damage: separate minima."}, {"code": "1.1.2.III", "node": "OP1.1.2", "name": "Number of metrics and indicators for linking enhanced NDC with National Sustainable Development Plan (NSDP) and their reporting.", "unit": "metrics/indicators", "definition": "Number of metrics and indicators for linking enhanced NDC with National Sustainable Development Plan (NSDP) and their reporting.\nBaseline: --\nMid-term: At least 4\nFinal target: At least 6\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Evidence of agreed indicators", "assumptions": "Sufficient political and institutional support are received to implement recommendations .", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": false, "final": 6, "disaggregation": null}, {"code": "1.1.3.I", "node": "OP1.1.3", "name": "Number of sectoral handbooks / protocols adopted (data collection, archiving, and data sharing).", "unit": "sectors with adopted handbooks/protocols", "definition": "Number of sectoral handbooks / protocols adopted (data collection, archiving, and data sharing).\nBaseline: --\nMid-term: Developed for at least 4 sectors.\nFinal target: Developed for at least 7 sectors (Forestry, Agriculture, Livestock, Energy, Transport, Industry, Waste)\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Evidence of handbooks / toolkits/protoco ls", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "PMU", "qualitative": false, "final": 7, "disaggregation": null}, {"code": "1.1.3.II", "node": "OP1.1.3", "name": "Number of sectoral data collection templates and guidelines.", "unit": "sectors with templates/guidelines", "definition": "Number of sectoral data collection templates and guidelines.\nBaseline: --\nMid-term: Developed for at least 4 sectors.\nFinal target: Developed for at least 7 sectors (Forestry, Agriculture, Livestock, Energy, Transport, Industry, Waste)\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Evidence of templates", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "PMU", "qualitative": false, "final": 7, "disaggregation": null}, {"code": "1.1.3.III", "node": "OP1.1.3", "name": "Number of MOUs signed between the stakeholders for collection, generation, archiving, and dissemination of data focusing on enhanced NDC climate change mitigation, adaptation, and addressing L&D for observed and potential climate change impacts (e.g. extreme weather events and slow onset events).", "unit": "signed MOUs", "definition": "Number of MOUs signed between the stakeholders for collection, generation, archiving, and dissemination of data focusing on enhanced NDC climate change mitigation, adaptation, and addressing L&D for observed and potential climate change impacts (e.g. extreme weather events and slow onset events).\nBaseline: --\nMid-term: At least 5 MOU signed between national agency/ministry related to ETF reporting.\nFinal target: At least 10 MOU signed between national agency/ministry related to ETF reporting.\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Signed MOU", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": false, "final": 10, "disaggregation": null}, {"code": "1.2.1.I", "node": "OP1.2.1", "name": "A qualitative gap assessment report on needs, constraints, and stakeholders on tracking climate finance on enhanced NDC actions.", "unit": "agencies/ministries assessed", "definition": "A qualitative gap assessment report on needs, constraints, and stakeholders on tracking climate finance on enhanced NDC actions.\nBaseline: --\nMid-term: At least 5 national agency/ministry related to climate finance identified and documented.\nFinal target: At least 10 national agency/ministry related to climate finance identified and documented.\nSource: CBIT Project Result Framework (1).docx, Annex A1. Numeric target measures assessment coverage of agencies/ministries, rather than number of reports.", "mov": "Status of gap assessment report containing summary/result of field visits, interviews and surveys with relevant line ministry/govern ment agency staff.", "assumptions": "Sufficient political and institutional support are received to implement recommendations .", "responsible": "PMU", "qualitative": false, "final": 10, "disaggregation": null}, {"code": "1.2.1.II", "node": "OP1.2.1", "name": "Published and adopted sectoral methodologies, guidelines, and protocols to collect, archive, and disseminate climate finance data, and training conducted on them.", "unit": "qualitative milestone / requirements", "definition": "Published and adopted sectoral methodologies, guidelines, and protocols to collect, archive, and disseminate climate finance data, and training conducted on them.\nBaseline: --\nMid-term: Developed for at least 4 sectors, and at least 2 training.\nFinal target: Developed for at least 7 sectors (Forestry, Agriculture, Livestock, Energy, Transport, Industry, Waste), and at least 4 training.\nSource: CBIT Project Result Framework (1).docx, Annex A1. Compound target retained in full; no aggregate count inferred.", "mov": "Evidence of methodologies, guidelines, and protocols, and training proceedings.", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "PMU", "qualitative": true, "final": null, "disaggregation": "Sector coverage and training events tracked separately."}, {"code": "1.2.1.III", "node": "OP1.2.1", "name": "Operational National Climate Finance Reporting and Monitoring (NCFRM) cell.", "unit": "qualitative milestone / requirements", "definition": "Operational National Climate Finance Reporting and Monitoring (NCFRM) cell.\nBaseline: --\nMid-term: Draft ToR and involved national agencies are identified for national ETF body for national ETF reporting.\nFinal target: Operational national ETF body through govt resolution for national ETF reporting.\nSource: CBIT Project Result Framework (1).docx, Annex A1. Source indicator names the NCFRM cell, but target wording refers to the national ETF body; retained for review.", "mov": "Evidence of agreements/ procedures/ TORs", "assumptions": "Sufficient political and institutional support are received to implement recommendations .", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": true, "final": null, "disaggregation": null}, {"code": "1.2.2.I", "node": "OP1.2.2", "name": "Number of knowledge products / best practice documents prepared and disseminated on monitoring and reporting of enhanced NDC adaptation actions.", "unit": "knowledge products/documents", "definition": "Number of knowledge products / best practice documents prepared and disseminated on monitoring and reporting of enhanced NDC adaptation actions.\nBaseline: --\nMid-term: At least 2\nFinal target: At least 4 (of which at least one gender case study)\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Evidence of knowledge products/ documents", "assumptions": "Sufficient political and institutional support are received to implement recommendations .", "responsible": "PMU", "qualitative": false, "final": 4, "disaggregation": "At least one gender case study among the four final knowledge products."}, {"code": "1.2.2.II", "node": "OP1.2.2", "name": "Number of training conducted and training module developed.", "unit": "training events", "definition": "Number of training conducted and training module developed.\nBaseline: --\nMid-term: At least 2 training.\nFinal target: At least 4 training.\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Training module and proceedings.", "assumptions": "Staff turnover will not undercut capacity development.", "responsible": "PMU", "qualitative": false, "final": 4, "disaggregation": null}, {"code": "2.1.1.I", "node": "OP2.1.1", "name": "Operational and enhanced online-based integrated MRV system.", "unit": "qualitative milestone / requirements", "definition": "Operational and enhanced online-based integrated MRV system.\nBaseline: MRV system exists, but it is not updated to meet the ETF.\nMid-term: Hardware and software procured for enhanced MRV system.\nFinal target: MRV system for the relevant sector are fully operational.\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Implementation report.", "assumptions": "Existing database systems and data can be linked with the proposed system.", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": true, "final": null, "disaggregation": null}, {"code": "2.1.1.II", "node": "OP2.1.1", "name": "Number of activity data collected, developed and archived for estimation of emissions sources and sinks.", "unit": "sectors with archived activity data", "definition": "Number of activity data collected, developed and archived for estimation of emissions sources and sinks.\nBaseline: Activity data and emissions factors of the previous national communication are not properly archived in centralized storage system.\nMid-term: Developed for at least 4 sectors.\nFinal target: Developed for at least 7 sectors (Forestry, Agriculture, Livestock, Energy, Transport, Industry, Waste)\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Number of activity data and emission factors archived and their time period.", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": false, "final": 7, "disaggregation": null}, {"code": "2.1.1.III", "node": "OP2.1.1", "name": "Number of country-specific emission factors collected, developed and archived for estimation of emissions sources and sinks.", "unit": "sectors with archived emission factors", "definition": "Number of country-specific emission factors collected, developed and archived for estimation of emissions sources and sinks.\nBaseline: Activity data and emissions factors of the previous national communication are not properly archived in centralized storage system.\nMid-term: Developed for at least 4 sectors.\nFinal target: Developed for at least 7 sectors (Forestry, Agriculture, Livestock, Energy, Transport, Industry, Waste)\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Number of activity data and emission factors archived and their time period.", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": false, "final": 7, "disaggregation": null}, {"code": "2.1.1.IV", "node": "OP2.1.1", "name": "Operational centralized database with sectoral linkages.", "unit": "qualitative milestone / requirements", "definition": "Operational centralized database with sectoral linkages.\nBaseline: --\nMid-term: Hardware and software procured.\nFinal target: Centralized database are fully operational.\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Implementation report.", "assumptions": "Existing database systems and data can be linked with the proposed system.", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": true, "final": null, "disaggregation": null}, {"code": "2.1.1.V", "node": "OP2.1.1", "name": "Operational integrated MRV system with online visualization and dissemination platform.", "unit": "qualitative milestone / requirements", "definition": "Operational integrated MRV system with online visualization and dissemination platform.\nBaseline: --\nMid-term: Hardware and software procured.\nFinal target: Integrated MRV system are fully operational.\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Implementation report.", "assumptions": "Existing MRV systems and data can be linked with the proposed system.", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": true, "final": null, "disaggregation": null}, {"code": "2.1.1.VI", "node": "OP2.1.1", "name": "Quality of MRV systems. Scale 3 Measurement systems are in place for a few activities, improved data quality and methodologies, but not cost or time efficient; wider access to reporting is still limited and information is partial; verification is rudimentary/non-standardized", "unit": "MRV quality scale", "definition": "Quality of MRV systems. Scale 3 Measurement systems are in place for a few activities, improved data quality and methodologies, but not cost or time efficient; wider access to reporting is still limited and information is partial; verification is rudimentary/non-standardized\nBaseline: An existing MRV system framework.\nMid-term: Hardware and software procured to upgrade the existing system. Scale 5: Measurement systems are strong for a limited set of activities and periodically report on key GHG related indicators i.e. mainstreamed into the activity implementation; reporting is improved through few pathways but limited audience and formats; verification limited\nFinal target: Scale 8. Strong standardized measurements processes established for key indicators and mainstreamed into institutional policy implementation; reporting is widely available in multiple formats; verification is done for a larger set of information\nSource: CBIT Project Result Framework (1).docx, Annex A1. Baseline column describes an existing MRV framework; Scale 3 appears in the indicator rubric and is not asserted as a measured baseline.", "mov": "Established MRV system and number of data stored.", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "MOCC PMU", "qualitative": true, "final": null, "disaggregation": null}, {"code": "2.1.2.I", "node": "OP2.1.2", "name": "Number of training organized (32 percent women participants).", "unit": "training events", "definition": "Number of training organized (32 percent women participants).\nBaseline: Limited systematic knowledge of GHG emissions and removals and reporting.\nMid-term: At least 5\nFinal target: At least 11\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Training assessment surveys", "assumptions": "Staff turnover will not undercut capacity development.", "responsible": "PMU", "qualitative": false, "final": 11, "disaggregation": "Women: 32 percent participation requirement."}, {"code": "2.1.2.II", "node": "OP2.1.2", "name": "Number of training knowledge materials including training proceedings and recorded video, and hosted on the online MRV system.", "unit": "knowledge materials", "definition": "Number of training knowledge materials including training proceedings and recorded video, and hosted on the online MRV system.\nBaseline: Limited systematic knowledge of GHG emissions and removals and reporting.\nMid-term: At least 5 knowledge materials.\nFinal target: At least 11 knowledge materials.\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Published proceedings and recorded training video.", "assumptions": "Staff turnover will not undercut capacity development.", "responsible": "PMU", "qualitative": false, "final": 11, "disaggregation": null}, {"code": "2.1.2.III", "node": "OP2.1.2", "name": "Number of national agencies exchanging the lessons learned at the national, regional, and global levels.", "unit": "sectors represented by participating agencies", "definition": "Number of national agencies exchanging the lessons learned at the national, regional, and global levels.\nBaseline: --\nMid-term: Organization representing at least 4 sectors.\nFinal target: Organization representing at least 7 sectors (Forestry, Agriculture, Livestock, Energy, Transport, Industry, Waste).\nSource: CBIT Project Result Framework (1).docx, Annex A1.", "mov": "Evidence of engagement.", "assumptions": "Stakeholders have sufficient intrinsic and extrinsic motivation to engage.", "responsible": "MOCC Department of Environment Protection and Conservation of Vanuatu & Department of Climate Change, PMU", "qualitative": false, "final": 7, "disaggregation": null}]$data$::jsonb) LOOP
   SELECT id INTO STRICT node_id FROM merl.framework_nodes WHERE project_id=pid AND node_code=item->>'node';
   INSERT INTO merl.project_indicators(project_id,code,name,unit,target_value,indicator_level,linked_level,framework_node_id,definition,means_of_verification,data_source,responsible_officer,assumptions,disaggregation,is_qualitative,direction,aggregation_method,progress_method)
   VALUES(pid,item->>'code',item->>'name',item->>'unit',(item->>'final')::numeric,'output','output',node_id,item->>'definition',item->>'mov','CBIT Project Result Framework (1).docx, Annex A1',item->>'responsible',item->>'assumptions',item->>'disaggregation',(item->>'qualitative')::boolean,
   CASE WHEN (item->>'qualitative')::boolean THEN 'qualitative' ELSE 'increase' END,
   CASE WHEN (item->>'qualitative')::boolean THEN 'qualitative' ELSE 'latest' END,
   CASE WHEN (item->>'qualitative')::boolean THEN 'qualitative' ELSE 'auto' END)
   ON CONFLICT(project_id,code) DO NOTHING;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements($data$[{"code": "1.1.1.I", "type": "baseline", "numeric": null, "ordinal": null, "text": null, "notes": "Source: CBIT Project Result Framework (1).docx, Annex A1. Numeric target measures assessment coverage of agencies/ministries, rather than number of reports. Baseline not specified in source."}, {"code": "1.1.1.I", "type": "mid_term", "numeric": 5, "ordinal": null, "text": "At least 5 national agency/ministry related to ETF reporting as identified in the stakeholder section should be reviewed, and documented.", "notes": "Source: CBIT Project Result Framework (1).docx, Annex A1. Numeric target measures assessment coverage of agencies/ministries, rather than number of reports."}, {"code": "1.1.1.I", "type": "final", "numeric": 10, "ordinal": null, "text": "At least 10 national agency/ministry related to ETF reporting as identified in the stakeholder section should be reviewed, and documented.", "notes": "Source: CBIT Project Result Framework (1).docx, Annex A1. Numeric target measures assessment coverage of agencies/ministries, rather than number of reports."}, {"code": "1.1.1.II", "type": "baseline", "numeric": null, "ordinal": null, "text": "Designated institutional working responsibilities exists for some ministry, but not sufficient for ETF.", "notes": "Source: CBIT Project Result Framework (1).docx, Annex A1."}, {"code": "1.1.1.II", "type": "mid_term", "numeric": null, "ordinal": null, "text": "Inter-ministerial agencies and other institutions identified for national MRV legal and regulatory framework.", "notes": "Source: CBIT Project Result Framework (1).docx, Annex A1."}, {"code": "1.1.1.II", "type": "final", "numeric": null, "ordinal": null, "text": "Formalized and published national MRV institutional terms of reference stating roles and responsibilities of stakeholders related to national MRV legal and regulatory framework.", "notes": "Source: CBIT Project Result Framework (1).docx, Annex A1."}, {"code": "